          label: 'ulg-sph-native-webgpu-surface-consumer-offscreen-validation-readback',
          size: readbackSizeBytes,
          usage: GPU_BUFFER_USAGE.MAP_READ | GPU_BUFFER_USAGE.COPY_DST
