        { texture: targets.texture },
        {
          buffer: bridge.offscreenValidationReadbackBuffer,
          bytesPerRow: readbackBytesPerRow,
          rowsPerImage: heightPx
        },
        {
          width: widthPx,
          height: heightPx,
          depthOrArrayLayers: 1
        }
