  function publishMlsMpmResidentStepArtifacts(step, signature, {
    stepsExecution = null,
    stepsSignature = null
  } = {}) {
    const residentExecutionGeneration = finiteNumberOrNull(
      stepsExecution?.residentExecutionGeneration
        ?? step?.residentExecutionGeneration
        ?? mlsMpmResidentExecutionGeneration
    );
    if (stepsExecution) {
      stepsExecution.residentExecutionGeneration = residentExecutionGeneration;
      stepsExecution.currentResidentExecutionGeneration = mlsMpmResidentExecutionGeneration;
      stepsExecution.signature = stepsSignature ?? stepsExecution.signature ?? null;
    }
    if (step) {
      step.residentExecutionGeneration = residentExecutionGeneration;
      step.currentResidentExecutionGeneration = mlsMpmResidentExecutionGeneration;
      step.signature = signature ?? step.signature ?? null;
    }
    mlsMpmResidentSteps = stepsExecution;
    mlsMpmResidentStepsSignature = stepsSignature;
    scene.userData.mlsMpmResidentSteps = stepsExecution;
    mlsMpmResidentStep = step;
    mlsMpmResidentStepSignature = stepsExecution ? null : signature;
    mlsMpmP2gGridProjection = step?.p2gGridProjection ?? null;
    mlsMpmP2gGridProjectionSignature = signature;
    mlsMpmGridUpdate = step?.gridUpdate ?? null;
    mlsMpmGridUpdateSignature = signature;
    mlsMpmG2pReconstruction = step?.g2pReconstruction ?? null;
    mlsMpmG2pReconstructionSignature = signature;
    scene.userData.mlsMpmResidentStep = step;
    scene.userData.mlsMpmP2gGridProjection = mlsMpmP2gGridProjection;
    scene.userData.mlsMpmGridUpdate = mlsMpmGridUpdate;
    scene.userData.mlsMpmG2pReconstruction = mlsMpmG2pReconstruction;
    const residentRenderSource = createResidentRenderSourceMetadata({
      residentSteps: stepsExecution,
      finalStep: step,
      residentExecutionGeneration,
      currentResidentExecutionGeneration: mlsMpmResidentExecutionGeneration,
      stepsSignature,
      stepSignature: signature,
      source: 'resident-step-publication'
    });
    scene.userData.mlsMpmResidentPublishedRenderSource = residentRenderSource;
    const markRenderArtifactStale = (target, reason) => {
      if (!target) return;
      target.residentRenderSourceStaleAfterPublish = true;
      target.residentRenderSourceStaleReason = reason;
      target.residentRenderSourceStaleAgainst = residentRenderSource;
      target.sourceResidentRenderSourceStatus = 'resident-render-source-stale-or-unknown';
      target.sourceResidentCurrentExecutionGeneration = residentRenderSource.currentResidentExecutionGeneration;
      target.sourceResidentExecutionGenerationMatchesCurrent = false;
      target.sourceResidentRetainedPrevious = true;
      target.sourceResidentRetentionReason = reason;
    };
    markRenderArtifactStale(
      sphResidentRenderState,
      'resident mechanics output was published after the last resident render refresh'
    );
    markRenderArtifactStale(
      sphResidentSurfaceDraw,
      'resident mechanics output was published after the current surface draw buffers'
    );
    markRenderArtifactStale(
      sphResidentSurfaceDrawRenderBridge,
      'resident mechanics output was published after the current render bridge'
    );
  }

  async function refreshSphGpuParticleBuffers({
    preferWebGpu = true,
    force = false,
    navigatorRef: overrideNavigatorRef = navigatorRef,
    device = null,
    deviceResult = null
  } = {}) {
    if (!sphGpuParticleState) {
      sphGpuParticleUpload = null;
      scene.userData.sphGpuParticleUpload = null;
      return null;
    }
    const sourceSphGpuParticleState = sphGpuParticleState;
    const signature = sphGpuParticleSignature(sourceSphGpuParticleState);
    if (!force && sphGpuParticleUploadSignature === signature && sphGpuParticleUpload) {
      return sphGpuParticleUpload;
    }
    if (!force && pendingSphGpuParticleUpload?.signature === signature) {
      return pendingSphGpuParticleUpload.promise;
    }
    const uploadGeneration = residentParticleUploadGeneration;
    const staleSphUpload = () => (
      !running
      || uploadGeneration !== residentParticleUploadGeneration
      || sphGpuParticleSignature(sphGpuParticleState) !== signature
    );
    const promise = (async () => {
      if (!preferWebGpu) {
        const upload = {
          schema: ULG_SPH_GPU_PARTICLE_BUFFER_SET_SCHEMA,
          status: 'not-requested',
          sourceSchema: sourceSphGpuParticleState.schema,
          particleCount: sourceSphGpuParticleState.particleCount,
          reason: 'WebGPU SPH particle upload not requested',
          scientificValidation: false,
          sphValidation: false,
          phaseChangeValidation: false,
          fullPhysicsValidation: false
        };
        if (staleSphUpload()) return { ...upload, status: 'stale-upload-discarded' };
        sphGpuParticleUpload = upload;
        sphGpuParticleUploadSignature = signature;
        scene.userData.sphGpuParticleUpload = upload;
        return upload;
      }
      const resolvedDeviceResult = device
        ? { status: 'webgpu-device-ready', reason: 'provided device', device }
        : (deviceResult || await requestCachedOpticalGpuDevice(overrideNavigatorRef));
      if (!resolvedDeviceResult.device) {
        const upload = {
          schema: ULG_SPH_GPU_PARTICLE_BUFFER_SET_SCHEMA,
          status: resolvedDeviceResult.status,
          sourceSchema: sourceSphGpuParticleState.schema,
          particleCount: sourceSphGpuParticleState.particleCount,
          reason: resolvedDeviceResult.reason,
          fallback: 'cpu-packed-buffer',
          scientificValidation: false,
          sphValidation: false,
          phaseChangeValidation: false,
          fullPhysicsValidation: false
        };
        if (staleSphUpload()) return { ...upload, status: 'stale-upload-discarded' };
        sphGpuParticleUpload = upload;
        sphGpuParticleUploadSignature = signature;
        scene.userData.sphGpuParticleUpload = upload;
        return upload;
      }
      if (staleSphUpload()) {
        return {
          schema: ULG_SPH_GPU_PARTICLE_BUFFER_SET_SCHEMA,
          status: 'stale-upload-discarded',
          sourceSchema: sourceSphGpuParticleState.schema,
          particleCount: sourceSphGpuParticleState.particleCount,
          reason: 'SPH particle state changed before WebGPU upload allocation',
          scientificValidation: false,
          sphValidation: false,
          phaseChangeValidation: false,
          fullPhysicsValidation: false
        };
      }
      const upload = uploadSphGpuParticleBuffers(resolvedDeviceResult.device, sourceSphGpuParticleState);
      upload.signature = signature;
      upload.step = sourceSphGpuParticleState.step;
      upload.time = sourceSphGpuParticleState.time;
      if (staleSphUpload()) {
        destroySphGpuParticleBuffers(upload);
        return { ...upload, status: 'stale-upload-discarded' };
      }
      if (sphGpuParticleUpload?.status === 'webgpu-uploaded') {
        destroySphGpuParticleBuffers(sphGpuParticleUpload);
      }
      sphGpuParticleUpload = upload;
      sphGpuParticleUploadSignature = signature;
      scene.userData.sphGpuParticleUpload = upload;
      return upload;
    })();
    pendingSphGpuParticleUpload = { signature, promise };
    try {
      return await promise;
    } finally {
      if (pendingSphGpuParticleUpload?.promise === promise) pendingSphGpuParticleUpload = null;
    }
  }

