            nextResidentSurfaceDraw.activeSurfaceCount = renderFieldSurfaceSummary?.activeSurfaceCount ?? 0;
            nextResidentSurfaceDraw.vertexCount = 0;
            nextResidentSurfaceDraw.triangleCount = 0;
